arguments.command:
cat > tests/prune_test.sh <<'EOF'
#!/bin/bash
# prune: sweeps var/audit with a 400-day retention (ADR-0015); never deletes younger files.
fail=0
d=$(mktemp -d)
RELAY_ROOT=$d bash bin/prune --dry-run >/dev/null || { echo "prune dry-run"; fail=1; }
mkdir -p "$d/var/audit" "$d/var/log/shift"
touch -d '399 days ago' "$d/var/audit/young.log"
touch -d '401 days ago' "$d/var/audit/old.log"
touch -d '100 days ago' "$d/var/audit/mid.log"
touch -d '401 days ago' "$d/var/log/shift/shift.log"
out=$(RELAY_ROOT=$d bash bin/prune --dry-run)
[ "$out" = "$d/var/audit/old.log" ] || { echo "dry-run lists: $out"; fail=1; }
RELAY_ROOT=$d bash bin/prune >/dev/null
[ ! -e "$d/var/audit/old.log" ] || { echo "old not removed"; fail=1; }
[ -e "$d/var/audit/young.log" ] && [ -e "$d/var/audit/mid.log" ] || { echo "young removed"; fail=1; }
[ -e "$d/var/log/shift/shift.log" ] || { echo "shift touched"; fail=1; }
rm -rf "$d"
exit $fail
EOF
bash tests/prune_test.sh; echo rc=$?
cat > lib/prune/paths.sh <<'EOF'
#!/bin/bash
# Paths the prune job touches. Audit logs live under var/audit (CHANGELOG 3.0.0), not var/log,
# which the host rotates.
PRUNE_AUDIT_DIR=var/audit
prune_root() { echo "${RELAY_ROOT:-.}"; }
prune_audit_dir() { echo "$(prune_root)/$PRUNE_AUDIT_DIR"; }
EOF
cat > lib/prune/retention.sh <<'EOF'
#!/bin/bash
# Retention for audit logs: 400 days (ADR-0015).
PRUNE_KEEP_DAYS=400
prune_keep_days() { echo "$PRUNE_KEEP_DAYS"; }
# find -mtime +N matches files at least N+1 days old, so +400 removes only files older than 400 full days.
prune_find_args() { echo "-type f -mtime +$(prune_keep_days)"; }
EOF
bash tests/prune_test.sh; echo rc=$?; bash scripts/verify.sh

